package pe.edu.solucionesweb.tramite.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="historial_tramites") public class HistorialTramite { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) private Tramite tramite; @Enumerated(EnumType.STRING) private EstadoTramite estado; private LocalDateTime fecha; private String responsable; private String observacion; @ManyToOne private Area area; public Long getId(){return id;} public Tramite getTramite(){return tramite;} public void setTramite(Tramite v){tramite=v;} public EstadoTramite getEstado(){return estado;} public void setEstado(EstadoTramite v){estado=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public String getResponsable(){return responsable;} public void setResponsable(String v){responsable=v;} public String getObservacion(){return observacion;} public void setObservacion(String v){observacion=v;} public Area getArea(){return area;} public void setArea(Area v){area=v;} }
